import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // Pooled numbered registers (kept)
    .reg .pred %p<16>;
    .reg .b32 %r<64>;
    .reg .b64 %rd<48>;
    .reg .f32 %f<16>;
    // Explicit named registers
    .reg .pred %pRowIn, %pColIn, %pEndK, %pDoL0, %pArowIn, %pKaIn, %pALoad, %pBrowIn, %pBcolIn, %pBLoad, %pDoL1, %pArowIn1, %pKaIn1, %pALoad1, %pBrowIn1, %pBcolIn1, %pBLoad1, %pEndKk, %pStore;
    .reg .b32  %rTx, %rTy, %rBx, %rBy, %rBDx, %rBDy, %rBR, %rBC, %rRow, %rCol, %rM, %rN, %rK;
    .reg .b32  %rK0, %rTid, %rL, %rArowT, %rAkT, %rRowA, %rKa, %rBkT, %rBcolT, %rBrow, %rColB;
    .reg .b32  %rL1, %rArowT1, %rAkT1, %rRowA1, %rKa1, %rBkT1, %rBcolT1, %rBrow1, %rColB1;
    .reg .b32  %rKk, %rOffA, %rOffB, %rSaOff0, %rSbOff0, %rSaOff1, %rSbOff1;
    .reg .b64  %rdA0, %rdB0, %rdC0, %rdA, %rdB, %rdC, %rdSA, %rdSB;
    .reg .b64  %rdTmp0, %rdTmp1, %rdTmp2, %rdTmp3, %rdTmpC;
    .reg .b64  %rdAddrA, %rdAddrB, %rdAddrA1, %rdAddrB1, %rdAddrC;
    .reg .b64  %rdOffA, %rdPtrA, %rdOffB, %rdPtrB, %rdSaOff0, %rdSaPtr0, %rdSbOff0, %rdSbPtr0, %rdSaOff1, %rdSaPtr1, %rdSbOff1, %rdSbPtr1;
    .reg .b64  %rdKa, %rdColB, %rdKa1, %rdColB1, %rdCol;
    .reg .f32  %fAcc, %fA0, %fB0, %fA1, %fB1;
    .shared .align 4 .b8 sA[2048]; // 16*32*4
    .shared .align 4 .b8 sB[2048]; // 32*16*4
    // Load parameters
    ld.param.u64 %rdA0, [A_ptr];
    ld.param.u64 %rdB0, [B_ptr];
    ld.param.u64 %rdC0, [C_ptr];
    ld.param.u32 %rM,  [M];
    ld.param.u32 %rN,  [N];
    ld.param.u32 %rK,  [K];
    cvta.to.global.u64 %rdA, %rdA0;
    cvta.to.global.u64 %rdB, %rdB0;
    cvta.to.global.u64 %rdC, %rdC0;
    // Thread/block indices
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    mov.u32 %rBDx, %ntid.x;   // expected 16
    mov.u32 %rBDy, %ntid.y;   // expected 16
    // Block base indices
    mul.lo.u32 %rBR, %rBy, %rBDy; // block row base
    mul.lo.u32 %rBC, %rBx, %rBDx; // block col base
    // Global row/col
    add.u32 %rRow, %rBR, %rTy;
    add.u32 %rCol, %rBC, %rTx;
    // Predicates for final store
    setp.lt.u32 %pRowIn, %rRow, %rM;
    setp.lt.u32 %pColIn, %rCol, %rN;
    // Shared base pointers
    mov.u64 %rdSA, sA;
    mov.u64 %rdSB, sB;
    // Accumulator
    mov.f32 %f0, 0f00000000;       // %f0 used as zero (kept but unused)
    mov.f32 %fAcc, 0f00000000;
    // K loop
    mov.u32 %rK0, 0;
K_loop:
    setp.ge.u32 %pEndK, %rK0, %rK;
    @%pEndK bra K_done;
    // Linear thread id within block
    mad.lo.s32 %rTid, %rTy, %rBDx, %rTx;
    // First load index l = tid
    mov.u32 %rL, %rTid;
    setp.lt.u32 %pDoL0, %rL, 512;
    @!%pDoL0 bra AfterLoad0;
    // A tile load for l
    shr.u32 %rArowT, %rL, 5;      // /32
    and.b32 %rAkT,   %rL, 31;     // % 32
    add.u32 %rRowA,  %rBR, %rArowT;
    add.u32 %rKa,    %rK0, %rAkT;
    setp.lt.u32 %pArowIn, %rRowA, %rM;
    setp.lt.u32 %pKaIn,   %rKa,   %rK;
    and.pred %pALoad, %pArowIn, %pKaIn;
    @%pALoad bra ALoad0_do;
    mov.f32 %fA0, 0f00000000;
    bra ALoad0_store;
ALoad0_do:
    mul.wide.u32 %rdTmp0, %rRowA, %rK;
    cvt.u64.u32  %rdKa,   %rKa;
    add.u64      %rdTmp0, %rdTmp0, %rdKa;
    shl.b64      %rdTmp0, %rdTmp0, 2;
    add.u64      %rdAddrA, %rdA, %rdTmp0;
    ld.global.nc.f32 %fA0, [%rdAddrA];
ALoad0_store:
    mad.lo.s32   %rSaOff0, %rArowT, 32, %rAkT;
    mul.wide.u32 %rdSaOff0, %rSaOff0, 4;
    add.u64      %rdSaPtr0, %rdSA, %rdSaOff0;
    st.shared.f32 [%rdSaPtr0], %fA0;
    // B tile load for l
    shr.u32 %rBkT,   %rL, 4;     // /16
    and.b32 %rBcolT, %rL, 15;    // %16
    add.u32 %rBrow,  %rK0, %rBkT;
    add.u32 %rColB,  %rBC, %rBcolT;
    setp.lt.u32 %pBrowIn, %rBrow, %rK;
    setp.lt.u32 %pBcolIn, %rColB, %rN;
    and.pred %pBLoad, %pBrowIn, %pBcolIn;
    @%pBLoad bra BLoad0_do;
    mov.f32 %fB0, 0f00000000;
    bra BLoad0_store;
BLoad0_do:
    mul.wide.u32 %rdTmp1, %rBrow, %rN;
    cvt.u64.u32  %rdColB, %rColB;
    add.u64      %rdTmp1, %rdTmp1, %rdColB;
    shl.b64      %rdTmp1, %rdTmp1, 2;
    add.u64      %rdAddrB, %rdB, %rdTmp1;
    ld.global.nc.f32 %fB0, [%rdAddrB];
BLoad0_store:
    mad.lo.s32   %rSbOff0, %rBkT, 16, %rBcolT;
    mul.wide.u32 %rdSbOff0, %rSbOff0, 4;
    add.u64      %rdSbPtr0, %rdSB, %rdSbOff0;
    st.shared.f32 [%rdSbPtr0], %fB0;
AfterLoad0:
    // Second load index l1 = l + 256
    add.u32 %rL1, %rL, 256;
    setp.lt.u32 %pDoL1, %rL1, 512;
    @!%pDoL1 bra AfterLoad1;
    // A tile load for l1
    shr.u32 %rArowT1, %rL1, 5;
    and.b32 %rAkT1,   %rL1, 31;
    add.u32 %rRowA1,  %rBR, %rArowT1;
    add.u32 %rKa1,    %rK0, %rAkT1;
    setp.lt.u32 %pArowIn1, %rRowA1, %rM;
    setp.lt.u32 %pKaIn1,   %rKa1,   %rK;
    and.pred %pALoad1, %pArowIn1, %pKaIn1;
    @%pALoad1 bra ALoad1_do;
    mov.f32 %fA1, 0f00000000;
    bra ALoad1_store;
ALoad1_do:
    mul.wide.u32 %rdTmp2, %rRowA1, %rK;
    cvt.u64.u32  %rdKa1,  %rKa1;
    add.u64      %rdTmp2, %rdTmp2, %rdKa1;
    shl.b64      %rdTmp2, %rdTmp2, 2;
    add.u64      %rdAddrA1, %rdA, %rdTmp2;
    ld.global.nc.f32 %fA1, [%rdAddrA1];
ALoad1_store:
    mad.lo.s32   %rSaOff1, %rArowT1, 32, %rAkT1;
    mul.wide.u32 %rdSaOff1, %rSaOff1, 4;
    add.u64      %rdSaPtr1, %rdSA, %rdSaOff1;
    st.shared.f32 [%rdSaPtr1], %fA1;
    // B tile load for l1
    shr.u32 %rBkT1,   %rL1, 4;
    and.b32 %rBcolT1, %rL1, 15;
    add.u32 %rBrow1,  %rK0, %rBkT1;
    add.u32 %rColB1,  %rBC, %rBcolT1;
    setp.lt.u32 %pBrowIn1, %rBrow1, %rK;
    setp.lt.u32 %pBcolIn1, %rColB1, %rN;
    and.pred %pBLoad1, %pBrowIn1, %pBcolIn1;
    @%pBLoad1 bra BLoad1_do;
    mov.f32 %fB1, 0f00000000;
    bra BLoad1_store;
BLoad1_do:
    mul.wide.u32 %rdTmp3, %rBrow1, %rN;
    cvt.u64.u32  %rdColB1, %rColB1;
    add.u64      %rdTmp3, %rdTmp3, %rdColB1;
    shl.b64      %rdTmp3, %rdTmp3, 2;
    add.u64      %rdAddrB1, %rdB, %rdTmp3;
    ld.global.nc.f32 %fB1, [%rdAddrB1];
BLoad1_store:
    mad.lo.s32   %rSbOff1, %rBkT1, 16, %rBcolT1;
    mul.wide.u32 %rdSbOff1, %rSbOff1, 4;
    add.u64      %rdSbPtr1, %rdSB, %rdSbOff1;
    st.shared.f32 [%rdSbPtr1], %fB1;
AfterLoad1:
    // Synchronize to ensure tiles are loaded
    bar.sync 0;
    // Compute on tile: kk in [0,32)
    mov.u32 %rKk, 0;
Kk_loop:
    setp.ge.u32 %pEndKk, %rKk, 32;
    @%pEndKk bra Kk_done;
    // Load A fragment: sA[ty, kk]
    mad.lo.s32   %rOffA, %rTy, 32, %rKk;
    mul.wide.u32 %rdOffA, %rOffA, 4;
    add.u64      %rdPtrA, %rdSA, %rdOffA;
    ld.shared.f32 %f2, [%rdPtrA];
    // Load B fragment: sB[kk, tx]
    mad.lo.s32   %rOffB, %rKk, 16, %rTx;
    mul.wide.u32 %rdOffB, %rOffB, 4;
    add.u64      %rdPtrB, %rdSB, %rdOffB;
    ld.shared.f32 %f3, [%rdPtrB];
    // FMA
    fma.rn.f32 %fAcc, %f2, %f3, %fAcc;
    add.u32 %rKk, %rKk, 1;
    bra Kk_loop;
Kk_done:
    // Sync before next tile loads overwrite shared memory
    bar.sync 0;
    // Next K tile
    add.u32 %rK0, %rK0, 32;
    bra K_loop;
K_done:
    // Store C if in bounds
    and.pred %pStore, %pRowIn, %pColIn;
    @!%pStore bra End;
    mul.wide.u32 %rdTmpC, %rRow, %rN;
    cvt.u64.u32  %rdCol,  %rCol;
    add.u64      %rdTmpC, %rdTmpC, %rdCol;
    shl.b64      %rdTmpC, %rdTmpC, 2;
    add.u64      %rdAddrC, %rdC, %rdTmpC;
    st.global.f32 [%rdAddrC], %fAcc;
End:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.dim() == 2 and B.dim() == 2, "Inputs must be 2D matrices"
        assert A.shape[1] == B.shape[0], "Incompatible shapes for matmul"
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"
        assert A.is_contiguous() and B.is_contiguous(), "Inputs must be contiguous"

        M = A.shape[0]
        K = A.shape[1]
        N = B.shape[1]

        C = torch.empty((M, N), device=A.device, dtype=A.dtype)

        module = _get_ptx_module()

        block_x = 16
        block_y = 16
        grid_x = (N + block_x - 1) // block_x
        grid_y = (M + block_y - 1) // block_y

        module.launch(
            "matmul_kernel",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, u32(M), u32(N), u32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

